package ke.co.krapin;
import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;
class ApplicationTest {@Test void applicationHasSandboxOrProductionBase(){var app=new Application();assertTrue(app.base.equals("https://sbx.kra.go.ke")||app.base.equals("https://api.kra.go.ke"));} @Test void catalogContainsAll22Services(){assertEquals(22,Application.SERVICES.size());} @Test void getCatalogPayloadIsEncodedAsQuery(){var app=new Application();var uri=app.targetUri("https://sbx.kra.go.ke/","/checker",java.util.Map.of("pin","A 1"),"GET");assertEquals("pin=A%201",uri.getRawQuery());} @Test void idempotencyFingerprintIsStableAndPayloadSensitive(){var app=new Application();assertEquals(app.idemDigest("{\"a\":1,\"b\":2}"),app.idemDigest("{\"a\":1,\"b\":2}"));assertNotEquals(app.idemDigest("{\"a\":1}"),app.idemDigest("{\"a\":2}"));} @Test void invalidProxyKeyIsRejectedBeforeUpstreamCall(){var app=new Application();var response=app.invoke("pin-checker-by-pin","invalid-key",null,java.util.Map.of("consent",true,"payload",java.util.Map.of()));assertEquals(401,response.getStatusCode().value());}}
